-- Same lockdown as 0001 for the blog tables, and stop Supabase's default
-- privileges from granting the API roles access to any FUTURE table we create.
DO $$
BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
		REVOKE ALL ON "blog_categories", "blog_posts", "blog_post_revisions" FROM anon, authenticated;
		REVOKE ALL ON SEQUENCE "blog_post_revisions_id_seq" FROM anon, authenticated;
		ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated;
		ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated;
		ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon, authenticated;
	END IF;
END $$;
--> statement-breakpoint
-- The three posts moved from WordPress (previously hard-coded in app/blog/posts.ts),
-- generated from that file so the text is byte-for-byte the same. Slugs are the
-- WordPress slugs, which next.config.js's redirects point at. Times are noon
-- Central on the original date, a minute apart to keep the original order.
INSERT INTO "blog_categories" ("name") VALUES ('Cash Flow & Strategy'), ('Business Credit')
ON CONFLICT ("name") DO NOTHING;
